import 'package:stac_framework/stac_framework.dart';

class StacWidgetParser extends StacParser<MyCustomWidget> {
  @override
  MyCustomWidget getModel(Map<String, dynamic> json) => MyCustomWidget.fromJson(json);

  @override
  Widget parse(BuildContext context, MyCustomWidget model) => Text(model.text);

  @override
  String get type => 'customWidget';
}
